pub enum SendSwaggerError {
    DefaultResponse(models::StatusResponse),
    UnknownValue(serde_json::Value),
}

/// # Errors
/// Returns a transport, decoding, or declared HTTP error.
pub async fn send_swagger(
    configuration: &configuration::Configuration,
) -> Result<String, Error<SendSwaggerError>> {
    let uri_str = format!("{}/api/v1/swagger.yaml", configuration.base_path);
    let mut req_builder = configuration.client.request(reqwest::Method::GET, &uri_str);
    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }
    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;
    let status = resp.status();
    let content_type = resp
        .headers()
        .get("content-type")
        .and_then(|value| value.to_str().ok())
        .unwrap_or("application/octet-stream");
    if status.is_success()
        && content_type
            .split(';')
            .next()
            .unwrap_or("")
            .trim()
            .eq_ignore_ascii_case("text/yaml")
    {
        return resp.text().await.map_err(Error::from);
    }
    let content_type = ContentType::from(content_type);
    let content = resp.text().await?;

    if !status.is_client_error() && !status.is_server_error() {
        match content_type {
            ContentType::Json => serde_json::from_str(&content).map_err(Error::from),
            ContentType::Text => Err(Error::from(serde_json::Error::custom("Received `text/plain` content type response that cannot be converted to `String`"))),
            ContentType::Unsupported(unknown_type) => Err(Error::from(serde_json::Error::custom(format!("Received `{unknown_type}` content type response that cannot be converted to `String`")))),
        }
    } else {
        let entity = {
            {
                serde_json::from_str(&content)
                    .map(SendSwaggerError::DefaultResponse)
                    .or_else(|_| serde_json::from_str(&content).map(SendSwaggerError::UnknownValue))
                    .ok()
            }
        };
        Err(Error::ResponseError(Box::new(ResponseContent {
            status,
            content,
            entity,
        })))
    }
}

